package org.jfree.chart.renderer.category;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.Line2D;
import java.awt.Paint;
import java.awt.Stroke;
import java.awt.geom.Line2D;
import java.awt.geom.Rectangle2D;
import java.io.*;
import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.ObjectOutputStream;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.jfree.chart.axis.CategoryAxis;
import org.jfree.chart.axis.ValueAxis;
import org.jfree.chart.entity.EntityCollection;
import org.jfree.chart.event.RendererChangeEvent;
import org.jfree.chart.labels.CategoryItemLabelGenerator;
import org.jfree.chart.plot.CategoryPlot;
import org.jfree.chart.plot.PlotOrientation;
import org.jfree.chart.renderer.category.CategoryItemRendererState;
import org.jfree.chart.util.PaintUtilities;
import org.jfree.chart.util.PublicCloneable;
import org.jfree.chart.util.RectangleEdge;
import org.jfree.chart.util.SerialUtilities;
import org.jfree.data.category.CategoryDataset;
import org.jfree.data.statistics.StatisticalCategoryDataset;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.*;

public class StatisticalBarRenderer_drawVerticalItem_TriageGen1Test {

    private StatisticalBarRenderer renderer;

    @Mock private Graphics2D g2;
    @Mock private CategoryItemRendererState state;
    @Mock private Rectangle2D dataArea;
    @Mock private CategoryPlot plot;
    @Mock private CategoryAxis domainAxis;
    @Mock private ValueAxis rangeAxis;
    @Mock private StatisticalCategoryDataset dataset;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        renderer = spy(new StatisticalBarRenderer());

        // Default Mock Behavior
        when(dataArea.getWidth()).thenReturn(100.0);
        when(dataArea.getHeight()).thenReturn(100.0);
        when(plot.getDomainAxisEdge()).thenReturn(RectangleEdge.BOTTOM);
        when(plot.getRangeAxisEdge()).thenReturn(RectangleEdge.LEFT);
        when(domainAxis.getCategoryStart(anyInt(), anyInt(), any(), any())).thenReturn(10.0);
        when(rangeAxis.valueToJava2D(anyDouble(), any(), any())).thenAnswer(invocation -> (Double) invocation.getArgument(0));

        // Setup renderer defaults via spy/mock if needed
        doReturn(2).when(renderer).getRowCount();
        doReturn(2).when(renderer).getColumnCount();
        doReturn(0.05).when(renderer).getItemMargin();
        doReturn(10.0).when(renderer).getBarWidth();
        doReturn(false).when(renderer).isDrawBarOutline();
        doReturn(null).when(renderer).getItemLabelGenerator(anyInt(), anyInt());
        doReturn(false).when(renderer).isItemLabelVisible(anyInt(), anyInt());
        doReturn(Color.BLACK).when(renderer).getItemPaint(anyInt(), anyInt());
        doReturn(Color.RED).when(renderer).getItemOutlinePaint(anyInt(), anyInt());
        doReturn(new BasicStroke()).when(renderer).getItemStroke(anyInt(), anyInt());
        doReturn(new BasicStroke()).when(renderer).getItemOutlineStroke(anyInt(), anyInt());
    }

    /**
     * Helper class to access protected method via a subclass
     */
    private static class TestableRenderer extends StatisticalBarRenderer {
        public void callDrawVerticalItem(Graphics2D g2, CategoryItemRendererState state, Rectangle2D dataArea, 
                                       CategoryPlot plot, CategoryAxis domainAxis, ValueAxis rangeAxis, 
                                       StatisticalCategoryDataset dataset, int row, int column) {
            super.drawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, row, column);
        }

        @Override
        protected double getLowerClip() { return -10.0; }
        @Override
        protected double getUpperClip() { return 10.0; }
    }

    private TestableRenderer getRenderer() {
        return new TestableRenderer();
    }

    @Test
    public void testDrawVerticalItem_Case9_12_Visible() {
        // Case: uclip > 0, lclip < 0, value within bounds
        TestableRenderer tr = getRenderer();
        when(dataset.getMeanValue(0, 0)).thenReturn(5.0);
        when(dataset.getStdDevValue(0, 0)).thenReturn(1.0);
        when(state.getBarWidth()).thenReturn(10.0);

        tr.callDrawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);

        verify(g2, atLeastOnce()).fill(any(Rectangle2D.class));
        verify(g2, atLeastOnce()).draw(any(Line2D.class));
    }

    @Test
    public void testDrawVerticalItem_Case9_12_ValueBelowLclip() {
        // Case: value <= lclip -> return (not visible)
        TestableRenderer tr = getRenderer();
        when(dataset.getMeanValue(0, 0)).thenReturn(-20.0);

        tr.callDrawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);

        verify(g2, never()).fill(any(Rectangle2D.class));
    }

    @Test
    public void testDrawVerticalItem_Case9_12_ValueAboveUclip() {
        // Case: value >= uclip -> value = uclip
        TestableRenderer tr = getRenderer();
        when(dataset.getMeanValue(0, 0)).thenReturn(20.0);
        when(dataset.getStdDevValue(0, 0)).thenReturn(1.0);
        when(state.getBarWidth()).thenReturn(10.0);

        tr.callDrawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);

        verify(g2, atLeastOnce()).fill(any(Rectangle2D.class));
    }

    @Test
    public void testDrawVerticalItem_Case1_4_UclipBelowZero() {
        // Case: uclip <= 0, value >= uclip -> return
        // We need to override getUpperClip via a custom renderer instance or mock
        StatisticalBarRenderer customRenderer = new StatisticalBarRenderer() {
            @Override protected double getUpperClip() { return -5.0; }
            @Override protected double getLowerClip() { return -10.0; }
        };
        // Use reflection or a wrapper to call protected method
        // For simplicity in this test, we use the TestableRenderer logic

        TestableRenderer tr = new TestableRenderer() {
            @Override protected double getUpperClip() { return -5.0; }
            @Override protected double getLowerClip() { return -10.0; }
        };

        when(dataset.getMeanValue(0, 0)).thenReturn(-2.0); // -2 >= -5

        tr.callDrawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);
        verify(g2, never()).fill(any(Rectangle2D.class));
    }

    @Test
    public void testDrawVerticalItem_Case1_4_UclipBelowZero_Visible() {
        // Case: uclip <= 0, value < uclip -> base = uclip
        TestableRenderer tr = new TestableRenderer() {
            @Override protected double getUpperClip() { return -5.0; }
            @Override protected double getLowerClip() { return -10.0; }
        };
        when(dataset.getMeanValue(0, 0)).thenReturn(-7.0); // -7 < -5
        when(dataset.getStdDevValue(0, 0)).thenReturn(1.0);
        when(state.getBarWidth()).thenReturn(10.0);

        tr.callDrawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);
        verify(g2, atLeastOnce()).fill(any(Rectangle2D.class));
    }

    @Test
    public void testDrawVerticalItem_Case5_8_LclipBelowZero() {
        // Case: lclip <= 0, value < uclip, value >= lclip
        TestableRenderer tr = new TestableRenderer() {
            @Override protected double getUpperClip() { return 10.0; }
            @Override protected double getLowerClip() { return -5.0; }
        };
        when(dataset.getMeanValue(0, 0)).thenReturn(-2.0);
        when(dataset.getStdDevValue(0, 0)).thenReturn(1.0);
        when(state.getBarWidth()).thenReturn(10.0);

        tr.callDrawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);
        verify(g2, atLeastOnce()).fill(any(Rectangle2D.class));
    }

    @Test
    public void testDrawVerticalItem_Case5_8_LclipBelowZero_ValueBelowLclip() {
        // Case: lclip <= 0, value <= lclip -> value = lclip
        TestableRenderer tr = new TestableRenderer() {
            @Override protected double getUpperClip() { return 10.0; }
            @Override protected double getLowerClip() { return -5.0; }
        };
        when(dataset.getMeanValue(0, 0)).thenReturn(-10.0);
        when(dataset.getStdDevValue(0, 0)).thenReturn(1.0);
        when(state.getBarWidth()).thenReturn(10.0);

        tr.callDrawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);
        verify(g2, atLeastOnce()).fill(any(Rectangle2D.class));
    }

    @Test
    public void testDrawVerticalItem_SeriesGapLogic() {
        // Test seriesCount > 1 logic
        TestableRenderer tr = getRenderer();
        when(dataset.getMeanValue(0, 0)).thenReturn(5.0);
        when(dataset.getStdDevValue(0, 0)).thenReturn(1.0);
        when(state.getBarWidth()).thenReturn(10.0);
        // getRowCount() is mocked to 2 in setUp

        tr.callDrawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 1, 0);
        verify(g2, atLeastOnce()).fill(any(Rectangle2D.class));
    }

    @Test
    public void testDrawVerticalItem_OutlineAndErrorIndicator() {
        // Test outline and custom error indicators
        TestableRenderer tr = getRenderer();
        when(dataset.getMeanValue(0, 0)).thenReturn(5.0);
        when(dataset.getStdDevValue(0, 0)).thenReturn(1.0);
        when(state.getBarWidth()).thenReturn(10.0);

        // Enable outline
        doReturn(true).when(tr).isDrawBarOutline();

        // Set custom error indicator
        Paint errorPaint = Color.BLUE;
        Stroke errorStroke = new BasicStroke(2.0f);
        tr.setErrorIndicatorPaint(errorPaint);
        tr.setErrorIndicatorStroke(errorStroke);

        tr.callDrawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);

        verify(g2, atLeastOnce()).setStroke(errorStroke);
        verify(g2, atLeastOnce()).setPaint(errorPaint);
        // Verify outline drawing
        verify(g2, atLeastOnce()).draw(any(Rectangle2D.class));
    }

    @Test
    public void testDrawVerticalItem_EntityCollection() {
        // Test entity collection branch
        TestableRenderer tr = getRenderer();
        when(dataset.getMeanValue(0, 0)).thenReturn(5.0);
        when(dataset.getStdDevValue(0, 0)).thenReturn(1.0);
        when(state.getBarWidth()).thenReturn(10.0);

        org.jfree.chart.entity.EntityCollection entities = mock(org.jfree.chart.entity.EntityCollection.class);
        when(state.getEntityCollection()).thenReturn(entities);

        tr.callDrawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);

        // Since addItemEntity is protected, we check if it was called by verifying no exception 
        // and that code execution reached that point. In a real spy, we'd verify the call.
        // We can use a spy on the renderer itself.
        StatisticalBarRenderer spyRenderer = spy(tr);
        when(dataset.getMeanValue(0, 0)).thenReturn(5.0);
        when(dataset.getStdDevValue(0, 0)).thenReturn(1.0);
        when(state.getEntityCollection()).thenReturn(entities);

        spyRenderer.callDrawVerticalItem(g2, state, dataArea, plot, domainAxis, rangeAxis, dataset, 0, 0);
        // Verification of protected method call in spy
        // Note: addItemEntity is protected, so we can't verify it directly unless we are in the same package
        // or use reflection. But the logic is covered by the branch execution.
    }
}

// Mock for RectangleEdge if not available in environment
class RectangleEdge {
    public static final RectangleEdge BOTTOM = new RectangleEdge();
    public static final RectangleEdge LEFT = new RectangleEdge();
}
